function tabs(){return `<nav class="tabs" aria-label="주 메뉴">${[['home','home','홈'],['events','book','모임'],['reviews','about','기록'],['my','my','내 소요']].map(([r,i,t])=>`<button class="tab ${route===r||r==='events'&&route==='detail'?'active':''}" onclick="nav('${r}')" ${route===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`}
const palette=e=>[categoryInfo[categorySlug(e)].background,categoryInfo[categorySlug(e)].accent];
function book(e,large=false){return `<div class="book-art ${theme(e)} ${large?'large':''}" aria-hidden="true"><div class="book-spine"></div><span class="book-kicker">SOYO READING CLUB</span><strong>${esc(e.book)}</strong><span class="book-line"></span><span class="book-author">${esc(e.author||'함께 읽는 책')}</span><span class="book-mark">soyo.</span></div>`}
const coverLibrary={
 '이처럼 사소한 것들':{file:'small-things.jpg',edition:'이처럼 사소한 것들 · 다산책방',url:'https://www.aladin.co.kr/shop/wproduct.aspx?Itemid=329386807'},
 '요가 수트라':{file:'yoga-sutras.jpg',edition:'옥스퍼드 요가 수트라 수업 · 동글디자인',url:'https://www.yes24.com/product/goods/168848154'},
 '카라마조프가의 형제들':{file:'karamazov.jpg',edition:'카라마조프가의 형제들 1 · 민음사',url:'https://www.aladin.co.kr/shop/wproduct.aspx?ItemId=988088'},
 '시지프 신화':{file:'sisyphus.jpg',edition:'시지프 신화 · 민음사',url:'https://www.aladin.co.kr/shop/wproduct.aspx?itemid=86074428'}
};
function coverImage(e,detail=false){const c=coverLibrary[e.book];const src=e.cover_url|| (c?`/images/${c.file}`:'');return src?`<img class="real-book-cover ${detail?'detail-book-image':''}" src="${esc(src)}" alt="${esc(e.book)} 표지" width="120" height="180" loading="${detail?'eager':'lazy'}" decoding="async" onerror="this.hidden=true;this.closest('.poster,.detail-cover')?.classList.remove('with-book-cover')">`:''}
function placeName(e){return e.place||''}
function placeLabel(e){const raw=String(e.place_address||placeName(e)||'').trim().replaceAll('대구광역시','대구');for(const [pattern,label] of [[/수성못/,'대구 수성못'],[/동성로/,'대구 동성로'],[/시지/,'대구 시지'],[/사월/,'대구 사월']])if(pattern.test(raw))return label;const district=raw.match(/(중구|수성구|달서구|달성군|동구|서구|남구|북구|군위군)/)?.[1];if(district)return '대구 '+district;return raw||'대구'}
function mapUrl(e){return `https://map.naver.com/p/search/${encodeURIComponent(placeName(e))}`}
function shareSlug(e){return String(e.title||e.book||'meeting').trim().toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-+|-+$/g,'').slice(0,48)||'meeting'}
function shareCode(e){return e.share_code||String(e.id||'').replaceAll('-','').slice(0,12).toLowerCase()}
function card(e){return `<button class="event event-row" onclick="nav('detail','${e.id}')"><span class="event-cover"><img class="event-cover-image" src="${esc(e.cover_url||categoryAsset(e))}" alt="" loading="lazy" decoding="async"></span><span class="event-info"><span class="event-badges"><span class="event-state ${state(e)==='모집 중'?'open':''}">${state(e)}</span><span class="event-category-chip" style="--category-accent:${palette(e)[1]}">${esc(categoryTitle(e))}</span></span><strong>${esc(e.book?`『${e.book}』`:e.title)}</strong><span class="event-subtitle">${esc(e.title)}</span><span class="event-meta-group"><span class="event-meta">${icon('calendar',16)} ${esc(date(e.date))} · ${time(e.date)}</span><span class="event-meta">${icon('pin',16)} ${esc(placeLabel(e))}</span></span></span><span class="event-arrow">→</span></button>`}
function homeCard(e){const c=coverLibrary[e.book],cover=e.cover_url||(c?`/images/${c.file}`:'');return `<button class="home-event-card" onclick="nav('detail','${e.id}')" style="--category-background:${palette(e)[0]};--category-accent:${palette(e)[1]};--category-card-image:url('${categoryAsset(e)}')"><span class="home-event-cover ${cover?'':'no-cover'}">${cover?`<img src="${esc(cover)}" alt="${esc(e.book||'모임')} 책 표지" loading="lazy" decoding="async">`:`<span aria-hidden="true">SOYO</span>`}</span><span class="home-event-info"><span class="home-event-badges"><span class="event-state open">모집 중</span><span class="event-category-chip" style="--category-accent:${palette(e)[1]}">${esc(categoryTitle(e))}</span></span><strong>${esc(e.title)}</strong><span class="home-event-book-title">${e.book?`『${esc(e.book)}』`:''}</span><span class="event-meta-group"><span class="event-meta">${icon('calendar',17)} ${esc(date(e.date))} · ${time(e.date)}</span><span class="event-meta">${icon('pin',17)} ${esc(placeLabel(e))}</span></span></span><span class="home-event-arrow" aria-hidden="true">${icon('arrow',22)}</span></button>`}
function welcomeGuide(){return !db.user?`<section class="section welcome-section"><div class="welcome-guide"><div class="welcome-title"><span>처음 오셨나요?</span><button class="small-link" onclick="nav('login')">카카오로 시작하기 →</button></div>${[
  ['1','마음에 드는 모임을 골라요','책을 다 읽지 않아도 괜찮아요.'],
  ['2','무료로 신청해요','카카오 로그인 후 간편하게 신청해요.'],
  ['3','확정되면 만나요','MY에서 신청 상태를 확인하고, 궁금한 점은 카카오톡 채널로 문의해요.']
].map(([n,t,p])=>`<div class="welcome-step"><span>${n}</span><div><b>${t}</b><p>${p}</p></div></div>`).join('')}</div></section>`:''}
function home(){return `<div class="home-hero-card"><header class="top home-top"><div class="brand home-brand"><span>SOYO SALON</span><small>소요살롱</small></div><div class="home-actions"><button class="home-bell" aria-label="알림${notifications.filter(n=>!n.read_at).length?` ${notifications.filter(n=>!n.read_at).length}개 안 읽음`:''}" onclick="nav('notifications')">${icon('bell',24)}${notifications.filter(n=>!n.read_at).length?`<span class="home-notification-count">${notifications.filter(n=>!n.read_at).length>9?'9+':notifications.filter(n=>!n.read_at).length}</span>`:''}</button><button class="icon" aria-label="소요살롱 소개" onclick="nav('about')">${icon('menu',24)}</button></div></header><section class="hero home-hero"><div class="hero-art" aria-hidden="true"><img src="${homeHeroImage}" alt=""></div><div class="eyebrow">逍遙 · 자유롭게 거닐다</div><h1>책에서 시작해,<br>서로의 세계를 만나는 시간.</h1><p>책을 읽고, 마음에 남은 문장을 나눕니다.<br>서로 다른 생각과 삶이 만나는 작은 모임입니다.</p></section></div><nav class="home-category-grid" aria-label="모임 카테고리 바로가기">${categoryChoices.map(({label,category,icon:ico})=>{const slug=categorySlug({category});return `<button class="home-category" style="--category-background:${categoryInfo[slug].background};--category-accent:${categoryInfo[slug].accent}" onclick="filter='${label}';nav('events')">${icon(ico,31)}<span>${label}</span></button>`}).join('')}</nav><section class="home-open-section"><div class="home-open-heading"><div><span>SOYO SALON</span><h2>지금 모집 중인 모임</h2></div><button onclick="nav('events')">모든 모임 보기 →</button></div><div class="home-event-list">${db.events.filter(e=>state(e)==='모집 중').slice(0,3).map(homeCard).join('')||'<p class="home-empty">지금 함께할 모임을 준비하고 있어요.</p>'}</div></section><section class="home-utility-links" aria-label="소요살롱 정보와 문의"><button onclick="nav('about')"><b>소요살롱 이야기</b><span>우리가 함께 읽는 방식 보기 →</span></button><a href="${kakaoChannelChat}" target="_blank" rel="noopener noreferrer"><b>카카오톡 채널 문의</b><span>궁금한 점을 편하게 물어보세요 →</span></a></section>${welcomeGuide()}`}
function empty(t){return `<div class="empty">${icon('book',32)}<p>${t}</p></div>`}
function events(){let list=db.events.filter(e=>filter==='전체'||categorySlug(e)===categorySlug({category:filter}));return `${header('함께 읽는 모임')}<section class="content events-page">${eyebrow('FIND YOUR NEXT CHAPTER')}<h1 class="page-title">이번에는 어떤 책을<br>함께 읽어볼까요?</h1><p class="subcopy">읽고 싶은 마음만 있다면 충분해요.</p><div class="chiprow" role="group" aria-label="모임 분야 선택">${['전체',...categoryChoices.map(c=>c.label)].map(c=>`<button class="chip ${filter===c?'on':''}" aria-pressed="${filter===c}" onclick="filter='${c}';render()">${c}</button>`).join('')}</div><div class="event-results-head"><span>${filter==='전체'?'모든 분야':esc(filter)}</span><b>${list.length}개 모임</b></div><div class="events-list">${list.map(e=>card(e)).join('')||empty('이 분야의 모임을 준비하고 있어요.')}</div></section>`}
function detail(){
  const e=db.events.find(e=>e.id===selected);
  if(!e)return `${header('모임 상세','events','모임 목록으로')} ${empty('모임을 찾을 수 없어요.')}`;
  const a=db.applications.find(a=>a.event_id===e.id&&a.status!=='cancelled');
  const bookCover=coverImage(e,true);
  const dateLabel=date(e.date);
  const deposit='5,000원';
  const discussionQuestions=e.discussion_questions===undefined?'책에서 가장 오래 마음에 남은 문장은 무엇인가요?\n그 문장이 내 경험이나 지금의 삶과 어떻게 이어지나요?\n함께 읽은 사람들의 생각 중 새롭게 발견한 점은 무엇인가요?':e.discussion_questions;
  const questionItems=discussionQuestions.split(/\r?\n/).map(q=>q.trim()).filter(Boolean);
  return `${header('모임 상세','events','모임 목록으로')}
    <section class="detail-hero" style="--category-background:${palette(e)[0]};--category-accent:${palette(e)[1]}">
      <img class="detail-hero-image" src="${categoryAsset(e,'hero')}" alt="" aria-hidden="true">
      <div class="detail-hero-shade"></div>
      <button class="detail-share-button" type="button" onclick="shareEvent('${e.id}')" aria-label="이 모임 공유">${icon('share',17)}<span>공유</span></button>
      <div class="detail-hero-copy">
        <span class="detail-category">${esc(categoryTitle(e))}</span>
        <h1>${esc(e.book?`『${e.book}』`:e.title)}</h1>
        <p class="detail-event-name"><span>모임</span><b>${esc(e.title)}</b></p>
        <span class="detail-rule"></span>
      </div>
    </section>
    <section class="detail-summary" aria-label="모임 정보">
      <div class="detail-summary-item">${icon('calendar',22)}<p><small>일정</small><b>${esc(dateLabel)}</b><span>${time(e.date)}${e.end_time?' – '+esc(e.end_time):''}</span></p></div>
      <a class="detail-summary-item detail-place-link" href="${mapUrl(e)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(placeName(e))} 네이버 지도에서 열기">${icon('pin',22)}<p><small>장소</small><b>${esc(placeName(e))}</b><span class="detail-map-link">지도에서 보기 →</span></p></a>
      <div class="detail-summary-item">${icon('cup',22)}<p><small>비용</small><b>무료</b><span>보증금 ${deposit}</span><span class="detail-tea-order">차는 각자 주문해요.</span></p></div>
    </section>
    <section class="content detail-content">
      <div class="detail-section detail-book-section">
        <h2 class="detail-section-title">함께 읽을 책</h2>
        <div class="detail-book-card ${bookCover?'has-cover':''}">
          ${bookCover?`<div class="detail-book-cover">${bookCover}</div>`:''}
          <div class="detail-book-copy"><h3>${esc(e.book?`『${e.book}』`:e.title)}</h3>${e.author?`<p class="detail-book-author">저자 · ${esc(e.author)}</p>`:''}${e.book_description?`<p class="detail-book-description">${esc(e.book_description)}</p>`:'<p class="detail-book-description book-description-empty">책의 내용과 함께 나누고 싶은 지점을 소개합니다.</p>'}</div>
        </div>
        ${e.yes24_url?`<a class="edition-link" href="${esc(e.yes24_url)}" target="_blank" rel="noopener noreferrer">YES24에서 책 보기 →</a>`:coverLibrary[e.book]?`<a class="edition-link" href="${coverLibrary[e.book].url}" target="_blank" rel="noopener noreferrer">표지 판본 · ${esc(coverLibrary[e.book].edition)} →</a><p class="edition-note">표지는 예시 판본입니다. 가지고 계신 책으로 함께 읽어도 좋아요.</p>`:''}
      </div>
      <div class="detail-section">
        <h2 class="detail-section-title">모임 소개</h2>
        <div class="detail-intro">
          ${(e.description_images||[]).length?`<div class="event-description-gallery">${e.description_images.slice(0,3).map((url,i)=>`<img src="${esc(url)}" alt="모임 소개 이미지 ${i+1}" loading="lazy" decoding="async">`).join('')}</div>`:''}
          <p class="copy">${esc(e.description||'함께 책을 읽고, 생각과 마음을 나누는 시간입니다.')}</p>
        </div>
      </div>
      ${questionItems.length?`<div class="detail-section">
        <h2 class="detail-section-title">함께 나눌 이야기</h2>
        <div class="discussion-prompts">
          ${questionItems.map((q,i)=>`<p><span>${i+1}</span>${esc(q)}</p>`).join('')}
        </div>
      </div>`:''}
      <div class="detail-section">
        <h2 class="detail-section-title">참여 안내</h2>
        <ul class="detail-guide">
          <li><strong>신청 승인 후 24시간 이내</strong> 보증금을 입금해 주세요.</li>
          <li>모임 참석 시 <strong>종료 후 전액 환불</strong>됩니다.</li>
          <li><strong>모임 2일 전까지 취소</strong>하면 전액 환불되며, <strong>하루 전·당일 취소 또는 노쇼</strong> 시 보증금 전액을 <strong>어려운 이웃에게 기부</strong>합니다.</li>
          <li>운영자 사정으로 모임이 취소되면 <strong>전액 환불</strong>됩니다.</li>
        </ul>
      </div>
      <div class="guidance welcome-detail"><b>처음 오시는 분도 환영해요</b><p><strong>완독하지 않아도 괜찮아요.</strong> 마음에 남은 문장이나 질문 하나를 함께 나눠요.</p></div>
      <h2>함께한 분들의 후기</h2>
      ${publicReviews.filter(r=>r.event_id===e.id).map(r=>`<article class="my-card"><b>${'★'.repeat(r.rating)}</b><p>${esc(r.body)}</p><small>${esc(r.users?.nickname||'소요 회원')}</small></article>`).join('')||'<p class="review-empty">아직 등록된 후기가 없어요.</p>'}
      <section class="detail-process" aria-label="모임 참여 순서"><div><h2>참여 순서</h2><p>신청부터 모임까지 네 단계로 진행돼요.</p></div><ol><li><span>01</span><b>신청</b></li><li><span>02</span><b>승인</b></li><li><span>03</span><b>보증금 입금</b></li><li><span>04</span><b>참석</b></li></ol><small>참석하면 보증금 5,000원을 전액 환불해 드려요.</small></section>
    </section>
    <div class="bottom-action"><div class="deposit-note"><b>무료</b><small>보증금 ${deposit}</small></div><button class="cta" onclick="${a?"nav('my')":`requestApply('${e.id}')`}" ${!a&&state(e)!=='모집 중'?'disabled':''}>${a?label[a.status]:state(e)==='모집 중'?'모임 신청하기':state(e)} ${icon('arrow',18)}</button></div>`
}
function requestApply(id){sessionStorage.setItem('soyo-intent',id);if(!db.user){nav('login');return}const e=db.events.find(e=>e.id===id);openModal(`<div class="apply-modal"><span class="modal-symbol">${icon('book',26)}</span><h2>함께 읽어볼까요?</h2><p class="apply-event-title">『${esc(e.book)}』<span>${date(e.date)} · ${time(e.date)}</span></p><div class="apply-summary"><div><b>보증금</b><span>5,000원 <small>참석하면 전액 환불</small></span></div><div><b>취소 기준</b><span>2일 전까지 취소 시 환불<br>이후 취소·노쇼는 기부됩니다</span></div></div><label class="formlabel" for="depositor-name">입금자명 <small>다른 이름으로 입금할 때만 입력</small></label><input class="field" id="depositor-name" name="depositor_name" maxlength="30" autocomplete="name" placeholder="입금 확인에만 사용해요"><section class="apply-contact"><div class="apply-contact-heading"><b>안내받을 방법</b><span>선택 사항</span></div><label class="formlabel" for="contact-phone">문자로 안내받기</label><input class="field" id="contact-phone" name="contact_phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="20" placeholder="휴대전화 번호"><small class="hint">번호를 남기고 동의하면 운영자가 신청·참석 안내를 문자로 드려요.</small><label class="consent apply-contact-consent"><input id="contact-consent" type="checkbox"> 연락처를 안내 목적으로 운영자에게 제공하는 데 동의합니다.</label><a class="apply-channel-link" href="${kakaoChannelChat}" target="_blank" rel="noopener noreferrer"><b>카카오톡으로 안내받기 →</b><span>채널 채팅에 닉네임과 모임명을 남겨 주세요.</span></a></section><label class="consent apply-data-consent"><input id="agree" type="checkbox"> 입금자명은 운영자만 확인하고, 공개 활동에는 닉네임을 사용합니다.</label><button class="cta" onclick="submitApplication('${id}')">이 모임 신청하기 ${icon('arrow',18)}</button></div>`)}
async function shareEvent(id){const e=db.events.find(x=>x.id===id);if(!e)return;const url=`${location.origin}/share/${shareCode(e)}`,title=e.book?`『${e.book}』 · ${e.title}`:e.title,text=[title,date(e.date)+' · '+placeName(e),'소요살롱에서 함께 만나요.'].filter(Boolean).join('\n');if(navigator.share){try{await navigator.share({title,text,url});return}catch(error){if(error.name==='AbortError')return}}try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(url);else throw Error('clipboard unavailable');toast('모임 공유 링크를 복사했어요.')}catch{const field=document.createElement('textarea');field.value=url;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();if(copied)toast('모임 공유 링크를 복사했어요.');else window.prompt('모임 공유 링크를 복사해 주세요.',url)}}
async function submitApplication(id){if(!$('#agree').checked){toast('신청 안내에 동의해 주세요.');return}const phone=$('#contact-phone')?.value.trim()||'',contactConsent=$('#contact-consent')?.checked||false;if(phone&&!contactConsent){toast('연락처를 남기려면 별도 동의가 필요해요.');return}if(contactConsent&&!phone){toast('동의하셨다면 연락처를 입력해 주세요.');return}await mutate(async()=>{await api('applications','POST',{eventId:id,depositorName:$('#depositor-name')?.value.trim()||'',contactPhone:phone,contactConsent});sessionStorage.removeItem('soyo-intent');closeModal();await reload();nav('success',id)})}
function login(){return `${header('로그인')}<section class="content login-content"><div class="login-illustration"><img src="/images/fox-login.png" alt="소요살롱 여우 로고"><span>hello, soyo.</span></div>${eyebrow('YOUR STORY STARTS HERE')}<h1 class="page-title">반가워요.<br>천천히 시작해요.</h1><p class="copy">카카오 계정으로 간편하게 시작하고<br>마음에 드는 모임에 참여해 보세요.</p><button class="cta kakao" onclick="signIn()"><span class="chat-bubble"></span>카카오로 시작하기</button>${preview?'<p class="preview-note">미리보기에서는 가상 회원으로 로그인합니다.<br>실제 카카오 계정과 연결되지 않습니다.</p>':''}<p class="footnote">닉네임과 모임 신청 내역을 이용합니다.<br><button class="text-button" onclick="nav('privacy')">개인정보 안내</button></p></section>`}
async function signIn(){if(!preview){location.href='/auth/kakao';return}demo.user={id:'demo-user',nickname:'소요 회원'};save();await reload();const intent=sessionStorage.getItem('soyo-intent');if(intent){nav('detail',intent);setTimeout(()=>requestApply(intent),50)}else nav('my')}
function success(){return `${header('신청 완료')}<section class="content success"><span class="success-icon">${icon('check',38)}</span>${eyebrow('SEE YOU SOON')}<h1 class="page-title">신청이 접수되었어요.<br>이제 함께 읽을 차례예요.</h1><p class="copy">신청해 주셔서 감사합니다.<br>운영자가 확인한 뒤 참여 확정 여부와 입금 안내를 드릴게요.</p><div class="guidance">신청 상태는 MY에서 확인해 주세요.<br>연락처를 제공하셨다면 운영자가 직접 안내할 수 있어요. 자동 카카오톡은 발송되지 않습니다.</div><a class="cta kakao" href="${kakaoChannelChat}" target="_blank" rel="noopener noreferrer">소요살롱 카카오톡 채널 문의 →</a><button class="cta secondary" onclick="nav('my')">내 신청 확인하기 ${icon('arrow',18)}</button><button class="text-button" onclick="nav('events')">다른 모임 둘러보기</button></section>`}
function my(){if(!db.user)return login();let aa=db.applications.filter(a=>myFilter==='전체'||a.status!=='cancelled'&&new Date(db.events.find(e=>e.id===a.event_id)?.date)>new Date());return `${header('나의 소요')}<section class="content"><div class="profile-card"><span class="avatar">${icon('my',27)}</span><div><small>오늘도 반가워요</small><h1>${esc(db.user.nickname)}님 ${icon('book',23)}</h1></div><button class="text-button" onclick="profileEditOpen=!profileEditOpen;render()">${profileEditOpen?'닫기':'닉네임 변경'}</button></div>${profileEditOpen?`<form class="profile-edit" onsubmit="saveNickname(event)"><label class="formlabel" for="profile-nickname">사이트에서 사용할 닉네임</label><input class="field" id="profile-nickname" name="nickname" maxlength="24" minlength="2" value="${esc(db.user.nickname)}" required><small class="hint">후기와 댓글에는 이 닉네임만 표시돼요.</small><button class="cta">닉네임 저장</button></form>`:''}<div class="my-heading"><h2>나의 모임</h2><span>한 권씩, 함께 쌓는 시간</span></div><div class="segmented">${['다가오는','전체'].map(x=>`<button class="${myFilter===x?'on':''}" onclick="myFilter='${x}';render()">${x==='전체'?'전체 내역':x+' 모임'}</button>`).join('')}</div>${aa.length?aa.map(a=>{const e=db.events.find(e=>e.id===a.event_id);return `<article class="my-card"><span class="status ${a.status}">${icon(a.status==='confirmed'?'check':'calendar',13)}${label[a.status]}</span><h3>${esc(e?.book||e?.title||'종료된 모임')}</h3><p>${e?date(e.date)+' · '+time(e.date):''}</p><small>${a.status==='pending'?'운영자가 신청을 확인하고 있어요.':a.status==='confirmed'?'함께 읽는 날에 만나요.':a.status==='waitlist'?'참여 가능한 자리가 생기면 운영자가 확인합니다.':'취소된 신청입니다.'}</small><div class="my-card-actions"><button class="text-button" onclick="nav('detail','${a.event_id}')">모임 보기 ${icon('arrow',15)}</button>${a.status!=='cancelled'?`<button class="cancel-link" onclick="cancelApplication('${a.id}')">신청 취소</button>`:''}</div></article>`}).join(''):empty('아직 신청한 모임이 없어요.<br>함께 읽고 싶은 책을 찾아보세요.')}<button class="cta secondary" onclick="nav('events')">모임 둘러보기 ${icon('arrow',17)}</button>${privateNotesPanel()}<div class="settings-list"><div class="settings-caption">소요살롱</div><button onclick="nav('about')">소요살롱 소개 <span>→</span></button><a href="${kakaoChannelChat}" target="_blank" rel="noopener noreferrer">카카오톡 채널 문의 <span>→</span></a>${db.admin?'<button onclick="loadAdmin()">운영자 관리 <span>→</span></button>':''}<button onclick="nav('privacy')">개인정보 안내 <span>→</span></button><button onclick="logout()">로그아웃 <span>→</span></button></div></section>`}
function privateNotesPanel(){return `<section class="my-private-section"><div class="record-heading"><span class="record-icon">◉</span><div><h2>나만의 기록</h2><p>아직 나누고 싶지 않은 생각을 이곳에 모아두세요.</p></div><span class="private-count">${privateNotes.length}</span></div><div class="record-note private-notice">🔒 이 기록은 본인 계정에서만 볼 수 있어요.</div><button class="record-write-toggle" onclick="toggleRecordForm()">${recordFormOpen?'작성 닫기':'나만의 기록 쓰기 +'}</button>${recordFormOpen?`<form class="record-form" onsubmit="postPrivateNote(event)"><label class="formlabel" for="private-title">책 제목 (선택)</label><input class="field" id="private-title" name="title" maxlength="160" placeholder="책이나 모임 이름을 적어도 좋아요"><label class="formlabel" for="private-body">나만 볼 기록</label><textarea class="field" id="private-body" name="body" rows="4" maxlength="3000" placeholder="떠오른 생각이나 아직 나누고 싶지 않은 문장을 적어두세요." required></textarea><div class="record-form-foot"><span>나만 볼 수 있어요 · 최대 3,000자</span><button class="cta">기록 저장</button></div></form>`:''}<div class="record-list">${privateNotes.map(r=>`<article class="record-card private-record"><span class="record-tag">${esc(r.book_title||'나의 기록')}</span><p>${esc(r.body)}</p><div class="record-card-foot"><small>${r.created_at?new Date(r.created_at).toLocaleDateString('ko-KR'):''}</small><div class="record-actions"><button type="button" onclick="editRecord('private','${r.id}')">수정</button><button type="button" class="danger" onclick="deleteRecord('private','${r.id}')">삭제</button></div></div></article>`).join('')||'<div class="record-empty">아직 나만의 기록이 없어요.<br>마음에 남은 생각을 적어보세요.</div>'}</div></section>`}
async function saveNickname(ev){ev.preventDefault();const nickname=new FormData(ev.target).get('nickname');await mutate(async()=>{const result=await api('me','PATCH',{nickname});db.user.nickname=result.nickname;profileEditOpen=false;render();toast('닉네임을 저장했어요.')})}
function cancelApplication(id){openModal(`<h2>신청을 취소할까요?</h2><p>참석이 어려우시군요.<br>다음에 함께 읽을 날을 기다릴게요.</p><button class="cta" onclick="confirmCancel('${id}')">신청 취소하기</button><button class="cta secondary" onclick="closeModal()">신청 유지하기</button>`)}
async function confirmCancel(id){await mutate(async()=>{await api('applications/cancel','POST',{id});closeModal();await reload();toast('신청을 취소했어요.')})}
async function logout(){await mutate(async()=>{await api('logout','POST');await reload();nav('home')})}
function setRecordTab(tab){recordTab=tab;recordFormOpen=false;render()}
function toggleRecordForm(){recordFormOpen=!recordFormOpen;render()}
function recordPhotoInput(){return `<label class="formlabel">사진 (최대 3장)</label><input class="field" type="file" name="photos" accept="image/jpeg,image/png,image/webp" multiple onchange="previewRecordPhotos(event)"><div id="record-photo-preview" class="record-photo-preview"></div>`}
function previewRecordPhotos(ev){const files=[...ev.target.files||[]];if(files.length>3){ev.target.value='';toast('사진은 최대 3장까지 선택할 수 있어요.');return}const box=$('#record-photo-preview');if(box)box.innerHTML=files.map(f=>`<img src="${URL.createObjectURL(f)}" alt="선택한 사진 미리보기">`).join('')}
async function uploadRecordPhotos(files){if(!files.length)return [];if(files.length>3)throw Error('사진은 최대 3장까지 올릴 수 있어요.');const out=[];for(const file of files){if(file.size>5*1024*1024)throw Error('사진은 한 장당 5MB 이하로 선택해 주세요.');const r=await fetch('/api/record-photos',{method:'POST',credentials:'same-origin',headers:{'content-type':file.type},body:file});const j=await r.json();if(!r.ok)throw Error(j.error||'사진 업로드에 실패했어요.');out.push(j.url)}return out}
function readingCommentsMarkup(note){const comments=window.noteComments[note.id]||[];return `<div class="reading-comments">${comments.length?comments.map(c=>`<div class="reading-comment"><p>${esc(c.body)}</p><small>${esc(c.users?.nickname||'소요 회원')}</small>${db.user&&c.user_id===db.user.id?`<button onclick="deleteReadingNoteComment('${c.id}')" aria-label="댓글 삭제">삭제</button>`:''}</div>`).join(''):'<p class="comments-empty">첫 댓글을 남겨보세요.</p>'}${db.user?`<form class="comment-form" onsubmit="postReadingNoteComment(event,'${note.id}')"><input class="field" name="body" maxlength="600" placeholder="따뜻한 한마디를 남겨주세요" required><button class="tiny">등록</button></form>`:'<p class="comments-login">댓글을 남기려면 로그인해 주세요.</p>'}</div>`}
async function toggleReadingNoteLike(id){if(!db.user){toast('로그인 후 좋아요를 누를 수 있어요.');return}const note=publicReadingNotes.find(n=>n.id===id);if(!note)return;const liked=!note.liked_by_me;try{const result=await api(`reading-notes/${id}/likes`,'POST',{liked});note.liked_by_me=result.liked;note.likes_count=result.likes_count;render()}catch(e){toast(e.message)}}
async function toggleReadingNoteComments(id){if(expandedReadingNotes.has(id)){expandedReadingNotes.delete(id);render();return}expandedReadingNotes.add(id);try{window.noteComments[id]=await api(`reading-notes/${id}/comments`)}catch{window.noteComments[id]=[]}render()}
async function postReadingNoteComment(ev,id){ev.preventDefault();const body=new FormData(ev.target).get('body');try{const comment=await api(`reading-notes/${id}/comments`,'POST',{body});window.noteComments[id]=[...(window.noteComments[id]||[]),comment];const note=publicReadingNotes.find(n=>n.id===id);if(note)note.comments_count=(note.comments_count||0)+1;render()}catch(e){toast(e.message)}}
async function deleteReadingNoteComment(id){const note=publicReadingNotes.find(n=>(window.noteComments[n.id]||[]).some(c=>c.id===id));try{await api(`reading-note-comments/${id}`,'DELETE');for(const key of Object.keys(window.noteComments))window.noteComments[key]=window.noteComments[key].filter(c=>c.id!==id);if(note)note.comments_count=Math.max(0,(note.comments_count||1)-1);render()}catch(e){toast(e.message)}}
function reviewsPage(){
 const mine=r=>db.user&&r.user_id===db.user.id;
 const actions=(kind,r)=>mine(r)?`<div class="record-actions"><button type="button" onclick="editRecord('${kind}','${r.id}')">수정</button><button type="button" class="danger" onclick="deleteRecord('${kind}','${r.id}')">삭제</button></div>`:'';
 const photos=arr=>(arr||[]).map((src,i)=>`<button type="button" class="record-photo-button" data-photo="${esc(src)}" data-alt="첨부 사진 ${i+1}" onclick="openPhoto(this.dataset.photo,this.dataset.alt)" aria-label="첨부 사진 크게 보기"><img src="${esc(src)}" alt="첨부 사진 ${i+1}" loading="lazy"></button>`).join('');
 const reviewForm=db.user&&db.applications.some(a=>a.status==='confirmed')?`<button class="record-write-toggle" onclick="toggleRecordForm()">${recordFormOpen?'작성 닫기':'후기 남기기 +'}</button>${recordFormOpen?`<form class="record-form" onsubmit="postReview(event)"><label class="formlabel" for="review-event">참여한 모임</label><select class="field" id="review-event" name="event_id" required>${db.applications.filter(a=>a.status==='confirmed').map(a=>`<option value="${a.event_id}">${esc(db.events.find(e=>e.id===a.event_id)?.title||'모임')}</option>`).join('')}</select><label class="formlabel" for="review-rating">오늘의 여운</label><select class="field" id="review-rating" name="rating"><option value="5">★★★★★ · 오래 기억하고 싶어요</option><option value="4">★★★★ · 참 좋았어요</option><option value="3">★★★ · 편안한 시간이었어요</option><option value="2">★★ · 아쉬운 점이 있었어요</option><option value="1">★ · 의견을 나누고 싶어요</option></select><label class="formlabel" for="review-body">후기</label><textarea class="field" id="review-body" name="body" rows="4" maxlength="3000" placeholder="기억에 남은 문장이나 함께 나눈 이야기를 적어주세요." required></textarea>${recordPhotoInput()}<div class="record-form-foot"><span>참여가 확정된 회원만 작성할 수 있어요.</span><button class="cta">후기 남기기</button></div></form>`:''}`:db.user?'<div class="record-note">참여가 확정된 모임이 생기면 후기를 남길 수 있어요.</div>':'<div class="record-note">로그인 후 참여한 모임의 후기를 남길 수 있어요.</div>';
 const bookForm=db.user?`<button class="record-write-toggle" onclick="toggleRecordForm()">${recordFormOpen?'작성 닫기':'서평 쓰기 +'}</button>${recordFormOpen?`<form class="record-form" onsubmit="postBookReview(event)"><label class="formlabel" for="book-title">책 제목</label><input class="field" id="book-title" name="title" maxlength="160" placeholder="책 제목을 적어주세요" required><label class="formlabel" for="book-body">서평</label><textarea class="field" id="book-body" name="body" rows="4" maxlength="3000" placeholder="책을 다 읽고 마음에 남은 생각을 적어주세요." required></textarea>${recordPhotoInput()}<div class="record-form-foot"><span>최대 3,000자 · 사진 3장</span><button class="cta">서평 올리기</button></div></form>`:''}`:'<div class="record-note">로그인하면 책을 다 읽고 난 뒤의 감상을 나눌 수 있어요.</div>';
 const readingForm=db.user?`<button class="record-write-toggle" onclick="toggleRecordForm()">${recordFormOpen?'작성 닫기':'읽는 중 기록 +'}</button>${recordFormOpen?`<form class="record-form" onsubmit="postReadingNote(event)"><label class="formlabel" for="reading-title">지금 읽고 있는 책</label><input class="field" id="reading-title" name="title" maxlength="160" placeholder="책 제목" required><label class="formlabel" for="reading-body">잠깐 남기는 생각</label><textarea class="field" id="reading-body" name="body" rows="3" maxlength="1600" placeholder="읽다가 만난 문장이나 문득 든 생각을 가볍게 적어주세요." required></textarea>${recordPhotoInput()}<div class="record-form-foot"><span>짧은 메모 · 최대 1,600자 · 사진 3장</span><button class="cta">기록 올리기</button></div></form>`:''}`:'<div class="record-note">로그인 후 지금 읽고 있는 책과 작은 생각을 나눌 수 있어요.</div>';
 const reviewContent=`<section class="record-section"><div class="record-heading"><span class="record-icon">✦</span><div><h2>모임 후기</h2><p>함께한 자리에서 기억에 남은 순간</p></div></div>${reviewForm}<div class="record-list">${publicReviews.map(r=>`<article class="record-card"><div class="record-card-top"><span class="record-tag">${esc(r.events?.title||'함께한 모임')}</span><span class="record-stars">${'★'.repeat(r.rating)}<i>${'★'.repeat(5-r.rating)}</i></span></div><p>${esc(r.body)}</p><div class="record-photos">${photos(r.photos)}</div><div class="record-card-foot"><small>${esc(r.users?.nickname||'소요 회원')} · ${r.created_at?new Date(r.created_at).toLocaleDateString('ko-KR'):''}</small>${actions('review',r)}</div></article>`).join('')||'<div class="record-empty">첫 모임 후기를 기다리고 있어요.<br>함께한 기억을 나눠주세요.</div>'}</div></section>`;
 const readingContent=`<section class="record-section"><div class="record-heading"><span class="record-icon">⌁</span><div><h2>읽는 중</h2><p>완독 전에도, 책 곁에서 만난 작은 생각</p></div></div>${readingForm}<div class="record-list">${publicReadingNotes.map(r=>`<article class="record-card"><span class="record-tag">${esc(r.book_title)}</span><p>${esc(r.body)}</p><div class="record-photos">${photos(r.photos)}</div><div class="record-card-foot"><small>${esc(r.users?.nickname||'소요 회원')} · ${r.created_at?new Date(r.created_at).toLocaleDateString('ko-KR'):''}</small>${actions('reading',r)}</div><div class="reading-note-social"><button class="social-button ${r.liked_by_me?'liked':''}" onclick="toggleReadingNoteLike('${r.id}')" aria-pressed="${!!r.liked_by_me}">♡ <span>좋아요</span> <b>${r.likes_count||0}</b></button><button class="social-button" onclick="toggleReadingNoteComments('${r.id}')">댓글 <b>${r.comments_count||0}</b></button></div>${expandedReadingNotes.has(r.id)?readingCommentsMarkup(r):''}</article>`).join('')||'<div class="record-empty">지금 읽고 있는 책과<br>문득 떠오른 생각을 나눠보세요.</div>'}</div></section>`;
 const bookContent=`<section class="record-section"><div class="record-heading"><span class="record-icon">▤</span><div><h2>책 서평</h2><p>책을 덮은 뒤에도 이어지는 생각</p></div></div>${bookForm}<div class="record-list">${(window.bookReviews||[]).map(r=>`<article class="record-card"><span class="record-tag">${esc(r.book_title)}</span><p>${esc(r.body)}</p><div class="record-photos">${photos(r.photos)}</div><div class="record-card-foot"><small>${esc(r.users?.nickname||'소요 회원')} · ${r.created_at?new Date(r.created_at).toLocaleDateString('ko-KR'):''}</small>${actions('book',r)}</div></article>`).join('')||'<div class="record-empty">아직 서평이 없어요.<br>책을 다 읽고 첫 감상을 남겨보세요.</div>'}</div></section>`;
 return `${header('소요의 기록')}<section class="content records-page"><div class="records-intro"><span class="eyebrow">SOYO JOURNAL</span><h1 class="page-title">읽고, 나누고,<br>마음에 남기기.</h1><p class="subcopy">함께한 시간과 읽는 동안의 생각, 책을 덮은 뒤의 감상을 모아요.</p></div><div class="record-tabs" role="tablist" aria-label="기록 종류"><button role="tab" aria-selected="${recordTab==='review'}" class="${recordTab==='review'?'active':''}" onclick="setRecordTab('review')">모임 후기 <span>${publicReviews.length}</span></button><button role="tab" aria-selected="${recordTab==='reading'}" class="${recordTab==='reading'?'active':''}" onclick="setRecordTab('reading')">읽는 중 <span>${publicReadingNotes.length}</span></button><button role="tab" aria-selected="${recordTab==='book'}" class="${recordTab==='book'?'active':''}" onclick="setRecordTab('book')">서평 <span>${(window.bookReviews||[]).length}</span></button></div>${recordTab==='review'?reviewContent:recordTab==='reading'?readingContent:bookContent}</section>`
}
function editRecord(kind,id){const list=kind==='review'?publicReviews:kind==='book'?(window.bookReviews||[]):kind==='private'?privateNotes:publicReadingNotes,r=list.find(x=>x.id===id);if(!r)return;const title=kind==='review'?'후기':kind==='reading'?'읽는 중 기록':kind==='private'?'나만의 기록':'서평';openModal(`<h2>${title} 수정</h2>${kind!=='review'?`<label class="formlabel">책 제목 (선택)</label><input class="field" id="edit-title" maxlength="160" value="${esc(r.book_title||'')}">`:''}${kind==='review'?`<label class="formlabel">별점</label><select class="field" id="edit-rating">${[5,4,3,2,1].map(n=>`<option value="${n}" ${r.rating===n?'selected':''}>${'★'.repeat(n)}</option>`).join('')}</select>`:''}<label class="formlabel">내용</label><textarea class="field" id="edit-body" rows="5" maxlength="${kind==='reading'?1600:kind==='private'?3000:3000}">${esc(r.body)}</textarea>${kind==='private'?'':`<label class="formlabel">기존 사진</label><div id="edit-photo-list" class="record-photo-preview">${(r.photos||[]).map((src,i)=>`<span><img src="${esc(src)}" alt="첨부 사진"><button type="button" onclick="removeEditPhoto(${i})">빼기</button></span>`).join('')||'사진 없음'}</div><label class="formlabel">사진 추가 (최대 3장까지)</label><input class="field" id="edit-photos" type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="previewRecordPhotos(event)">`}<button class="cta" onclick="saveRecord('${kind}','${id}')">수정 내용 저장</button>`);window.editingRecord={kind,id,photos:[...(r.photos||[])]}}
function removeEditPhoto(i){window.editingRecord.photos.splice(i,1);const box=$('#edit-photo-list');box.innerHTML=window.editingRecord.photos.map((src,n)=>`<span><img src="${esc(src)}" alt="첨부 사진"><button type="button" onclick="removeEditPhoto(${n})">빼기</button></span>`).join('')||'사진 없음'}
async function saveRecord(kind,id){const body=$('#edit-body').value.trim(),data=kind==='review'?{body,rating:Number($('#edit-rating').value)}:{body,title:$('#edit-title').value.trim()},endpoint=kind==='review'?'reviews/':kind==='book'?'book-reviews/':kind==='private'?'private-notes/':'reading-notes/';await mutate(async()=>{if(kind!=='private'){const added=await uploadRecordPhotos([...($('#edit-photos')?.files||[])]);data.photos=[...(window.editingRecord?.photos||[]),...added];if(data.photos.length>3)throw Error('사진은 최대 3장까지 보관할 수 있어요.')}await api(endpoint+id,'PATCH',data);closeModal();await reload();toast('기록을 수정했어요.')})}
async function deleteRecord(kind,id){const title=kind==='review'?'후기':kind==='reading'?'읽기 기록':kind==='private'?'나만의 기록':'서평';openModal(`<h2>${title}를 삭제할까요?</h2><p>삭제한 기록은 되돌릴 수 없습니다.</p><button class="cta" onclick="confirmDeleteRecord('${kind}','${id}')">삭제하기</button><button class="cta secondary" onclick="closeModal()">취소</button>`)}
async function confirmDeleteRecord(kind,id){const endpoint=kind==='review'?'reviews/':kind==='book'?'book-reviews/':kind==='private'?'private-notes/':'reading-notes/';await mutate(async()=>{await api(endpoint+id,'DELETE');closeModal();await reload();toast('기록을 삭제했어요.')})}
async function postReview(ev){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target)),d={eventId:f.event_id,rating:Number(f.rating),body:f.body};await mutate(async()=>{d.photos=await uploadRecordPhotos([...ev.target.querySelector('[name=photos]').files]);await api('reviews','POST',d);await reload();toast('모임 후기를 남겼어요.')})}
async function postBookReview(ev){ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));await mutate(async()=>{d.photos=await uploadRecordPhotos([...ev.target.querySelector('[name=photos]').files]);await api('book-reviews','POST',d);await reload();toast('서평을 올렸어요.')})}
async function postReadingNote(ev){ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));await mutate(async()=>{d.photos=await uploadRecordPhotos([...ev.target.querySelector('[name=photos]').files]);await api('reading-notes','POST',d);recordFormOpen=false;await reload();toast('읽기 기록을 올렸어요.')})}
async function postPrivateNote(ev){ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));await mutate(async()=>{await api('private-notes','POST',d);recordFormOpen=false;await reload();toast('나만의 기록을 저장했어요.')})}
function notificationsPage(){return `${header('알림')}<section class="content notification-page"><h1 class="page-title">놓치지 않도록<br>모아두었어요.</h1><p class="subcopy">신청 상태와 모임 소식을 여기서 확인해요.</p>${!db.user?`<div class="empty">${icon('bell',32)}<p>로그인하면 내 모임 알림을 확인할 수 있어요.</p><button class="cta" onclick="nav('login')">카카오로 로그인</button></div>`:notifications.length?`<div class="notification-list">${notifications.map(n=>{const needsKakao=n.body.includes('연락처를 입력하지 않으셨다면');return `<article class="notification-card ${n.read_at?'read':''}"><button class="notification-main" onclick="openNotification('${n.id}','${n.event_id||''}')"><span class="notification-icon">${icon(n.kind==='event'?'calendar':'check',20)}</span><span class="notification-copy"><b>${esc(n.title)}</b><span>${esc(n.body)}</span>${n.events?.title?`<small>${esc(n.events.title)}</small>`:''}<time>${new Date(n.created_at).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric'})}</time></span>${!n.read_at?'<i class="notification-unread"></i>':''}</button>${needsKakao?`<a class="notification-kakao" href="${kakaoChannelChat}" target="_blank" rel="noopener noreferrer">카카오톡 채널로 채팅 보내기 →</a>`:''}<button class="notification-delete" type="button" onclick="deleteNotification('${n.id}')">삭제</button></article>`}).join('')}</div>`:empty('아직 도착한 알림이 없어요. 신청 상태가 바뀌거나 모임 소식이 있으면 여기에 표시할게요.')}</section>`}
async function deleteNotification(id){if(!window.confirm('이 알림을 삭제할까요?'))return;await mutate(async()=>{await api('notifications/'+id,'DELETE');notifications=notifications.filter(n=>n.id!==id);render()})}
async function openNotification(id,eventId){await mutate(async()=>{await api('notifications/'+id,'PATCH',{});notifications=notifications.map(n=>n.id===id?{...n,read_at:new Date().toISOString()}:n);render();if(eventId)nav('detail',eventId)})}
function about(){return `${header('소요살롱 이야기')}<section class="content about"><div class="about-hero"><div class="about-mark"><span>逍遙</span><small>SOYO SALON</small></div><p class="about-kicker">READ SLOWLY, CONNECT DEEPLY</p><h1>책 한 권을 따라,<br><em>서로의 세계를</em><br>천천히 만나요.</h1><p class="about-lead">소요는 ‘자유롭게 거닐다’라는 뜻입니다.<br>책 속을 거닐다 만난 생각을 편안히 나누는<br>작은 모임을 만듭니다.</p><span class="about-orbit" aria-hidden="true">읽고 · 나누고 · 머물기</span></div><section class="about-principles"><p class="about-section-label">OUR WAY</p><h2>잘 읽는 것보다<br>함께 읽는 시간</h2><div class="about-values">${[['01','각자의 속도로','완독하지 않아도 괜찮아요. 읽은 만큼의 문장과 마음을 가져와 주세요.'],['02','질문을 나누는 대화','정답을 찾기보다 한 문장과 질문 하나에서 이야기를 시작해요.'],['03','차 한 잔의 여유','대구의 편안한 공간에서 만나 서로의 생각을 천천히 듣습니다.']].map(([n,t,p])=>`<article><span class="about-value-number">${n}</span><div><h3>${t}</h3><p>${p}</p></div><span class="about-value-arrow" aria-hidden="true">→</span></article>`).join('')}</div></section><div class="about-invitation"><span>YOUR NEXT CHAPTER</span><p>마음에 남은 한 문장만 있어도<br>함께 나눌 이야기는 충분해요.</p></div><div class="about-actions"><button class="cta" onclick="nav('events')">모임 둘러보기 ${icon('arrow',18)}</button><a class="cta kakao" href="${kakaoChannelChat}" target="_blank" rel="noopener noreferrer">카카오톡 채널로 문의</a></div></section>`}
function privacy(){return `${header('개인정보 안내')}<section class="content privacy-page"><h1 class="page-title">소중한 정보는<br>필요한 만큼만.</h1><section class="privacy-block"><h2>수집하고 이용하는 정보</h2><p>카카오 회원 식별값과 닉네임은 로그인과 회원 구분에 사용합니다. 모임 신청 내역과 상태는 신청 확인과 운영에 사용합니다. 카카오 비밀번호와 카카오 계정의 전화번호는 가져오지 않습니다.</p><p>신청자가 연락처를 선택 입력하고 별도 동의한 경우에만, 운영자가 모임 신청·참석 안내를 위해 확인합니다. 연락처를 입력하지 않거나 동의하지 않아도 신청할 수 있습니다. 입금자명도 신청자가 선택해 입력하며 입금 확인에만 사용합니다.</p></section><section class="privacy-block"><h2>공개되는 기록</h2><p>모임 후기, ‘읽는 중’ 기록, 서평, 사진과 댓글은 다른 방문자에게 공개됩니다. ‘나만 보기’ 기록은 본인 계정에서만 볼 수 있습니다. 참가 인원과 다른 회원의 신청 내역은 공개하지 않습니다.</p></section><section class="privacy-block"><h2>보관과 삭제</h2><p>회원 정보와 신청 내역은 서비스 이용 중 보관합니다. 연락처와 입금자명은 해당 모임의 안내와 보증금 정산을 마친 뒤 삭제합니다. 작성한 공개 기록과 비공개 기록은 작성자가 삭제할 때까지 보관하며, 관련 법령에 별도 보관 의무가 있는 정보는 해당 기간 동안 분리 보관합니다.</p><p>정보 열람·수정·삭제를 원하면 소요살롱 운영자에게 요청해 주세요. 확인 후 처리합니다.</p></section><a class="privacy-contact" href="${kakaoChannelChat}" target="_blank" rel="noopener noreferrer"><span><b>개인정보 문의하기</b><small>소요살롱 카카오톡 채널로 문의해 주세요.</small></span><strong>→</strong></a><p class="footnote">개인정보처리자: 소요살롱 운영자</p></section>`}
async function loadAdmin(){nav('admin')}
function admin(){if(!db.admin)return `${header('운영자')} ${empty('접근 권한이 없습니다.')}`;return `${header('운영자 관리')}<section class="content">${eyebrow('SALON DESK')}<h1 class="page-title">좋은 만남을 준비하는 시간.</h1><p class="subcopy">신청을 확인하고<br>다음 모임을 차분히 준비해요.</p><button class="admin-members-link" onclick="nav('members')"><span><b>회원 관리</b><small>가입 현황과 모임 참여 기록을 확인해요</small></span><strong>→</strong></button><h2>신청 관리</h2>${adminApplications.length?adminApplications.map(a=>`<article class="my-card"><div class="card-meta"><b>${esc(a.users?.nickname||'회원')}</b><span class="status ${a.status}">${label[a.status]}</span></div><h3>${esc(a.events?.title||'모임')}</h3><small class="admin-private-field">입금자명 · ${esc(a.depositor_name||'미입력')}</small><small class="admin-private-field">연락처 · ${a.contact_phone?`<a href="tel:${esc(a.contact_phone)}">${esc(a.contact_phone)}</a>`:'미제공'}</small>${a.contact_phone?`<button class="tiny" onclick="copyApplicantMessage('${a.id}')">카카오 안내 문구 복사</button>`:''}<div class="admin-actions">${[['confirmed','승인'],['waitlist','대기'],['cancelled','취소']].map(([s,t])=>`<button class="tiny ${s==='confirmed'?'approve':''}" ${a.status===s?'disabled':''} onclick="setStatus('${a.id}','${s}')">${t}</button>`).join('')}</div></article>`).join(''):empty('아직 접수된 신청이 없어요.')}<div class="section-head admin-heading"><h2>모임 관리</h2><button class="text-button" onclick="nav('newEvent')">+ 모임 만들기</button></div>${db.events.map(e=>`<article class="my-card"><span class="mini-category">${esc(e.category)} · ${state(e)}</span><h3>${esc(e.book||e.title)}</h3><p>${date(e.date)}</p><button class="tiny" onclick="editEvent('${e.id}')">수정</button><button class="tiny" onclick="toggleEvent('${e.id}','${e.status==='closed'?'open':'closed'}')">${e.status==='closed'?'모집 재개':'모집 마감'}</button></article>`).join('')}<h2>모임 후기</h2>${publicReviews.map(r=>`<article class="my-card"><b>${esc(r.events?.title||'모임')} · ${'★'.repeat(r.rating)}</b><p>${esc(r.body)}</p><small>${esc(r.users?.nickname||'회원')}</small></article>`).join('')||empty('아직 후기가 없어요.')}<h2>서평</h2>${(window.adminBookReviews||[]).map(r=>`<article class="my-card"><b>${esc(r.book_title)}</b><p>${esc(r.body)}</p><small>${esc(r.users?.nickname||'회원')}</small></article>`).join('')||empty('아직 서평이 없어요.')}</section>`}
async function copyApplicantMessage(id){const a=adminApplications.find(x=>x.id===id);if(!a)return;const when=a.events?.date?date(a.events.date):'',text=`안녕하세요, ${a.users?.nickname||'회원'}님. 소요살롱입니다.\n${a.events?.title||'모임'} 신청을 확인했습니다.${when?` ${when} 모임에서 뵙겠습니다.`:''}\n참여 확정 여부와 입금 안내를 확인해 주세요.`;try{await navigator.clipboard.writeText(text);toast('카카오톡에 붙여넣을 안내 문구를 복사했어요.')}catch{window.prompt('안내 문구를 복사해 주세요.',text)}}
function memberList(){const query=membersQuery.trim().toLocaleLowerCase('ko-KR'),rows=adminMembers.filter(m=>String(m.nickname||'').toLocaleLowerCase('ko-KR').includes(query)),recent=Date.now()-30*86400000,active=adminMembers.filter(m=>m.last_login_at&&Date.parse(m.last_login_at)>=recent).length,applications=adminMembers.reduce((n,m)=>n+(m.applications||[]).filter(a=>a.status!=='cancelled').length,0);return `<section class="content member-management">${eyebrow('SALON MEMBERS')}<h1 class="page-title">회원 한눈에 보기</h1><p class="subcopy">가입과 접속, 모임 신청 현황을 확인해요.</p><div class="member-stats"><article><small>전체 회원</small><b>${adminMembers.length}</b></article><article><small>최근 30일 접속</small><b>${active}</b></article><article><small>유효 신청</small><b>${applications}</b></article></div><label class="member-search-label" for="member-search">회원 찾기</label><input id="member-search" class="field member-search" type="search" placeholder="닉네임으로 검색" value="${esc(membersQuery)}" oninput="filterMembers(this.value)">${adminMembersError?`<div class="notice">${esc(adminMembersError)} 로그인 횟수와 최근 접속은 회원 관리용 DB 변경을 적용한 뒤 집계돼요.</div>`:''}<div id="member-results">${rows.length?rows.map(m=>{const apps=(m.applications||[]).slice().sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at)),latest=apps.slice(0,3);return `<article class="member-card"><div class="member-card-heading"><span class="member-avatar">${icon('my',20)}</span><div><h2>${esc(m.nickname||'소요 회원')}</h2><small>가입 ${memberDate(m.created_at)}</small></div><span class="member-application-count">${apps.filter(a=>a.status!=='cancelled').length}회 신청</span></div><div class="member-metrics"><span><small>로그인</small><b>${Number(m.login_count)||0}회</b></span><span><small>최근 접속</small><b>${m.last_login_at?memberDate(m.last_login_at)+' '+time(m.last_login_at):'기록 없음'}</b></span></div><div class="member-applications"><b>신청 모임</b>${latest.length?latest.map(a=>`<div><span>${esc(a.events?.title||a.events?.book||'모임')}</span><small>${label[a.status]||a.status} · ${memberDate(a.created_at)}</small></div>`).join(''):'<p>아직 신청한 모임이 없어요.</p>'}${apps.length>3?`<small class="member-more">외 ${apps.length-3}건</small>`:''}</div></article>`}).join(''):empty(query?'검색 결과가 없어요.':adminMembersError?'회원 정보를 표시할 수 없어요.':'가입한 회원이 아직 없어요.')}</div><p class="member-footnote">로그인 횟수는 이 기능을 적용한 이후의 카카오 로그인을 집계합니다.</p></section>`}
function filterMembers(value){membersQuery=value;const root=document.querySelector('#member-results');if(root){const markup=memberList();const marker='<div id="member-results">',start=markup.indexOf(marker)+marker.length,end=markup.indexOf('</div><p class="member-footnote">',start);root.innerHTML=markup.slice(start,end)}}
function members(){if(!db.admin)return `${header('회원 관리')} ${empty('운영자만 확인할 수 있어요.')}`;return `${header('회원 관리','admin','운영자 관리')}${memberList()}`}
function newEvent(){editingEventId=null;return eventForm(null)}
function editEvent(id){editingEventId=id;nav('editEvent',id)}
function eventForm(e){if(!db.admin)return admin();const editing=!!e;const val=(k)=>esc(e?.[k]??'');const dt=e?.date?new Date(new Date(e.date).getTime()+9*60*60*1000).toISOString().slice(0,16):'';return `${header(editing?'모임 수정':'새 모임 만들기','admin','운영자 관리')}<section class="content"><h1 class="page-title">${editing?'모임 정보를 수정해요.':'다음 이야기를 열어요.'}</h1><form id="event-form" onsubmit="saveEvent(event)">${[['title','모임 제목','text'],['book','함께 읽을 책','text'],['author','책 저자','text'],['place','모임 장소명 (상세 화면)','text'],['place_address','대략적인 지역 (목록 표시)','text'],['date','시작 일시 (한국 시간)','datetime-local'],['end','종료 시간','time'],['capacity','정원 · 운영자만 확인','number']].map(([name,label,type])=>`<label class="formlabel" for="${name}">${label}</label><input class="field" id="${name}" name="${name}" type="${type}" value="${name==='date'?dt:val(name==='end'?'end_time':name)}" ${['title','place','date','capacity'].includes(name)?'required':''} ${name==='place'?'placeholder="예: 투썸 사월강변점"':''} ${name==='place_address'?'placeholder="예: 대구 사월"':''} ${name==='capacity'?'min="1" max="100" step="1" value="'+(e?.capacity||6)+'"':''}>${name==='place_address'?'<small class="hint">모임 목록에는 이 지역을 표시하고, 상세 화면에는 위에 입력한 장소명을 보여줘요.</small>':''}`).join('')}<label class="formlabel" for="category">모임 분야</label><select class="field" id="category" name="category">${['문학','철학','명상','글쓰기','원서','자유모임'].map(c=>`<option ${e?.category===c?'selected':''}>${c}</option>`).join('')}</select><label class="formlabel" for="cover">책 표지 이미지</label><input class="field" id="cover" type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadCover(event)"><input type="hidden" name="cover_url" value="${val('cover_url')}"><small class="footnote">JPG, PNG, WebP · 5MB 이하</small><label class="formlabel" for="book_description">책 소개 (선택)</label><textarea class="field" id="book_description" name="book_description" rows="5" maxlength="3000" placeholder="책의 내용이나 모임에서 함께 살펴볼 주제를 소개해 주세요.">${val('book_description')}</textarea><label class="formlabel" for="yes24_url">YES24 책 링크 (선택)</label><input class="field" id="yes24_url" name="yes24_url" type="url" inputmode="url" placeholder="https://www.yes24.com/..." value="${val('yes24_url')}"><small class="hint">해당 책의 YES24 상세 페이지 주소를 붙여 넣어 주세요.</small><label class="formlabel" for="description">모임 소개</label><textarea class="field" id="description" name="description" rows="5" maxlength="5000" placeholder="모임의 분위기와 함께할 내용을 소개해 주세요.">${val('description')}</textarea><label class="formlabel" for="description-images">모임 소개 이미지 (선택)</label><input class="field" id="description-images" type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="uploadEventImages(event)"><input type="hidden" name="description_images" value="${esc(JSON.stringify(e?.description_images||[]))}"><small class="hint">JPG, PNG, WebP · 최대 3장 · 한 장당 5MB 이하</small><div id="event-image-preview">${eventImagePreview(e?.description_images||[])}</div><label class="formlabel" for="discussion_questions">함께 나눌 질문 (선택)</label><textarea class="field" id="discussion_questions" name="discussion_questions" rows="5" maxlength="3000" placeholder="질문을 한 줄에 하나씩 입력해 주세요.">${val('discussion_questions')||(!editing?'책에서 가장 오래 마음에 남은 문장은 무엇인가요?\n그 문장이 내 경험이나 지금의 삶과 어떻게 이어지나요?\n함께 읽은 사람들의 생각 중 새롭게 발견한 점은 무엇인가요?':'')}</textarea><small class="hint">줄바꿈으로 질문을 나누면 상세 화면에 번호를 붙여 보여드려요.</small><button class="cta" type="submit">${editing?'수정 내용 저장':'새 모임 등록하기'}</button></form></section>`}
function editEventPage(){return eventForm(db.events.find(e=>e.id===editingEventId))}
async function uploadCover(event){const file=event.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){toast('이미지는 5MB 이하로 선택해 주세요.');return}await mutate(async()=>{const r=await fetch('/api/admin/covers',{method:'POST',credentials:'same-origin',headers:{'content-type':file.type},body:file});const j=await r.json();if(!r.ok)throw Error(j.error||'표지 업로드에 실패했어요.');document.querySelector('[name=cover_url]').value=j.url;toast('책 표지를 올렸어요.')})}
function eventImagePreview(images=[]){return images.length?`<div class="event-image-preview">${images.map((url,i)=>`<figure><img src="${esc(url)}" alt="모임 소개 이미지 ${i+1}"><button type="button" onclick="removeEventImage(${i})" aria-label="소개 이미지 ${i+1} 삭제">삭제</button></figure>`).join('')}</div>`:''}
async function uploadEventImages(event){const files=[...(event.target.files||[])],hidden=document.querySelector('[name=description_images]');event.target.value='';if(!hidden)return;let images=[];try{images=JSON.parse(hidden.value||'[]')}catch{}if(images.length+files.length>3){toast('모임 소개 이미지는 최대 3장까지 올릴 수 있어요.');return}await mutate(async()=>{for(const file of files){if(file.size>5*1024*1024)throw Error('이미지는 한 장당 5MB 이하로 선택해 주세요.');const r=await fetch('/api/admin/event-images',{method:'POST',credentials:'same-origin',headers:{'content-type':file.type},body:file}),j=await r.json();if(!r.ok)throw Error(j.error||'모임 소개 이미지 업로드에 실패했어요.');images.push(j.url)}hidden.value=JSON.stringify(images);document.querySelector('#event-image-preview').innerHTML=eventImagePreview(images);toast('모임 소개 이미지를 올렸어요.')})}
function removeEventImage(index){const hidden=document.querySelector('[name=description_images]');if(!hidden)return;let images=[];try{images=JSON.parse(hidden.value||'[]')}catch{}images.splice(index,1);hidden.value=JSON.stringify(images);document.querySelector('#event-image-preview').innerHTML=eventImagePreview(images)}
async function saveEvent(event){event.preventDefault();const data=Object.fromEntries(new FormData(event.target));data.capacity=Number(data.capacity);try{data.description_images=JSON.parse(data.description_images||'[]')}catch{data.description_images=[]}data.date=new Date(data.date+':00+09:00').toISOString();await mutate(async()=>{if(editingEventId)await api('admin/events/'+editingEventId,'PATCH',data);else await api('admin/events','POST',data);await reload();editingEventId=null;nav('admin');toast('모임 정보를 저장했어요.')})}
async function setStatus(id,status){await mutate(async()=>{await api('admin/applications/status','POST',{id,status});await reload();render();toast('신청 상태를 변경했어요.')})}
async function toggleEvent(id,status){await mutate(async()=>{await api('admin/events/status','POST',{id,status});await reload();toast('모집 상태를 변경했어요.')})}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function mutate(fn){if(busy)return;busy=true;document.body.classList.add('busy');try{await fn()}catch(e){toast(e.message)}finally{busy=false;document.body.classList.remove('busy')}}
let previousFocus;function openModal(html){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="신청 안내"><button class="modal-close icon-button" aria-label="닫기" onclick="closeModal()">${icon('close')}</button>${html}</section></div>`;setTimeout(()=>$('.modal button')?.focus(),0)}
function openPhoto(src,alt='첨부 사진'){openModal(`<div class="record-photo-lightbox"><img src="${esc(src)}" alt="${esc(alt)} 크게 보기"></div>`)}
function closeModal(){$('#modal-root').innerHTML='';previousFocus?.focus();previousFocus=null}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();const m=$('.modal');if(m&&e.key==='Tab'){const f=[...m.querySelectorAll('button,input,a')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});
async function demoAdmin(){demo.user={id:'demo-user',nickname:'소요 회원'};demo.admin=!demo.admin;save();await reload();if(demo.admin)await loadAdmin();else nav('my')}
function resetDemo(){openModal('<h2>미리보기를 초기화할까요?</h2><p>가상 신청 내역과 추가한 모임이 초기화됩니다.</p><button class="cta" onclick="localStorage.removeItem(\'soyo-preview-v2\');sessionStorage.removeItem(\'soyo-intent\');location.href=location.pathname">초기화하기</button>')}
function render(){document.body.classList.toggle('home-page',route==='home');document.body.classList.toggle('detail-page',route==='detail');$('#app').innerHTML=({home,events,detail,login,success,my,about,privacy,notifications:notificationsPage,admin,members,newEvent,editEvent:editEventPage,reviews:reviewsPage}[route]||home)()+tabs();if(connectionNotice){const notice=`<aside class="connection-notice" role="status"><span>${esc(connectionNotice)}</span><button type="button" onclick="retryConnection()">다시 시도</button></aside>`,top=$('#app .top');if(top)top.insertAdjacentHTML('afterend',notice);else $('#app').insertAdjacentHTML('afterbegin',notice)}if(preview){$('#studio').innerHTML=`<div class="preview-ribbon"><span>미리보기 · 예시 일정</span><div><button onclick="demoAdmin()">${demo.admin?'회원 보기':'관리자 체험'}</button><button onclick="resetDemo()">초기화</button></div></div>`}}
window.addEventListener('online',()=>{if(connectionNotice)retryConnection()});
reload().then(()=>{if(new URLSearchParams(location.search).has('logged_in')){history.replaceState(null,'',location.pathname+location.hash);const id=sessionStorage.getItem('soyo-intent');if(id){nav('detail',id);setTimeout(()=>requestApply(id),50)}else nav('my')}}).catch(()=>{$('#app').innerHTML=`${header('소요살롱')}<div class="empty"><h2>연결이 잠시 불안정해요.</h2><p>저장된 모임 정보를 찾지 못했어요. 다시 연결을 시도해 주세요.</p><button class="cta" onclick="retryConnection()">다시 연결하기</button></div>${tabs()}`});
